import type { ArtifactModelProviderMetadata } from '../types/artifact-model';
import type { ArtifactModelResponseMetadata } from '../types/artifact-model-response-metadata';
import type { Warning } from '../types/warning';
import type { GeneratedArtifact } from './generated-artifact';

/**
 * The result of an `experimental_generateArtifact` call.
 */
export interface GenerateArtifactResult {
  /**
   * The first artifact that was generated.
   */
  readonly artifact: GeneratedArtifact;

  /**
   * All artifacts generated by the model.
   */
  readonly artifacts: Array<GeneratedArtifact>;

  /**
   * Warnings for the call, e.g. unsupported settings.
   */
  readonly warnings: Array<Warning>;

  /**
   * Response metadata from each provider call.
   */
  readonly responses: Array<ArtifactModelResponseMetadata>;

  /**
   * Provider-specific metadata passed through from the provider.
   */
  readonly providerMetadata: ArtifactModelProviderMetadata;
}
